  def create(client, task, input) do
    path = "/api/v1/tasks/#{ArchAstro.SDK.Path.encode(task)}/links"
    ArchAstro.SDK.HTTP.request(client, :post, path, body: input, decode: {:map, :unknown})
  end
end
